/**
 * 计算确定性短哈希，保证同一节点每次渲染得到相同的梗名。
 * @param {string} input
 * @returns {number}
 */
function stableHash(input = '') {
  let h = 2166136261;
  const s = String(input);
  for (let i = 0; i < s.length; i += 1) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h >>> 0);
}

/**
 * 推导成员的职责分桶，优先按职责关键词，其次按模型家族。
 * @param {any} member
 * @returns {string}
 */
function detectNicknameBucket(member = {}) {
  const id = String(member.agent || member.id || member.name || '').toLowerCase();
  const roleStr = String(member.role || member.geminekoRole || '').toLowerCase();
  const model = String(member.model || '').toLowerCase();

  if (member.isCoordinator || id === 'coordinator' || roleStr === 'coordinator') return 'coordinator';
  if (/review|audit|verifier|strict|check/.test(id) || /claude|sonnet|opus|haiku/.test(model)) return 'reviewer';
  if (/gpt|codex|\bsol\b|\bastra\b|\bo1\b|\bo3\b|\bo4\b/.test(id) || /gpt|codex|\bsol\b|\bastra\b|\bo1\b|\bo3\b/.test(model)) return 'gpt';
  if (/scout|explore|search|spy/.test(id)) return 'scout';
  if (/wiki|doc|note/.test(id)) return 'wiki';
  if (/carbon|ultra|argon/.test(model) || /carbon/.test(roleStr)) return 'carbon';
  if (/neon|\bpro\b/.test(model) || /neon/.test(roleStr)) return 'neon';
  if (/hydrogen|flash|lite/.test(model) || /hydrogen/.test(roleStr)) return 'hydrogen';
  return 'hydrogen';
}

/**
 * 根据 Swarm 成员信息生成“高浓度哈基米梗名”与悬浮提示信息。
 * @param {any} member 成员对象，含 `agent`/`id`/`name`, `model`, `role`, `action`
 * @param {{ enabled?: boolean, usedNames?: Set<string> }} [options]
 * @returns {{ displayName: string, memeName: string, originalTag: string, tooltip: string, bucket: string }}
 */
function resolveMemeNickname(member = {}, options = {}) {
  const rawId = String(member.agent || member.id || member.name || 'worker').replace(/^@/, '');
  const originalTag = `@${rawId}`;
  const bucket = detectNicknameBucket(member);
  const pool = ROLE_NAME_POOLS[bucket] || ROLE_NAME_POOLS.hydrogen;
  const usedNames = options.usedNames instanceof Set ? options.usedNames : null;

  let picked = pool[stableHash(rawId) % pool.length];
  if (usedNames && usedNames.has(picked)) {
    const startIdx = stableHash(rawId) % pool.length;
    let found = null;
    for (let i = 1; i < pool.length; i += 1) {
      const candidate = pool[(startIdx + i) % pool.length];
      if (!usedNames.has(candidate)) {
        found = candidate;
        break;
      }
    }
    if (found) {
      picked = found;
    } else {
      const idx = (stableHash(rawId) % 9) + 1;
      picked = `${picked}#${idx}`;
    }
  }
  if (usedNames) usedNames.add(picked);

  const enabled = options.enabled !== false;
  const modelText = member.model ? ` · ${member.model}` : '';
  const actionText = member.actionLabel ? ` [${member.actionLabel}]` : '';

  return {
    displayName: enabled ? picked : originalTag,
    memeName: picked,
    originalTag,
    tooltip: `${picked} (${originalTag}${modelText})${actionText}`,
    bucket,
  };
}


// === pixel-sprites ===
/**
 * Gemineko Hive 32×32 高精复古像素精灵绘制器（纯 Canvas，无需外链图）。
 * 支持角色：queen / neon / hydrogen / carbon / claude / gpt 以及「全员彩色哈基米」色相映射。
 * 支持动作：thinking / reading / editing / running / asking / idle。
 */

function hslToHex(h, s, l) {
  h = ((h % 360) + 360) % 360;
  s /= 100;
  l /= 100;
  const k = (n) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  return '#' + [f(0), f(8), f(4)].map((x) => Math.round(x * 255).toString(16).padStart(2, '0')).join('');
}

function hashStr(s) {
  let h = 7;
  for (const ch of String(s || '')) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return h;
}

const HACHIMI_HUES = [245, 290, 200, 325, 34, 165, 270, 15, 218, 138];

/**
 * 为指定角色名和色相计算像素调色板。
 * @param {string} kind
 * @param {string} memberName
 * @param {string} roleMode
 */
function resolvePixelPalette(kind, memberName, roleMode) {
  const k = String(kind || 'neon').toLowerCase();
  if (roleMode === 'all-hachimi' && k !== 'queen') {
    const baseHue =
      memberName !== 'coordinator'
        ? HACHIMI_HUES[hashStr(memberName) % HACHIMI_HUES.length]
        : 245;
    return {
      outline: '#2D2148',
      hair: hslToHex(baseHue, 74, 72),
      hairDark: hslToHex(baseHue + 10, 62, 54),
      hairTip: hslToHex(baseHue + 42, 76, 76),
      earInner: '#F9A8D4',
      skin: '#FFF0EA',
      blush: '#FDA4AF',
      eyeLeft: '#C084FC',
      eyeRight: '#F59E0B',
      collar: '#1E1B4B',
      accent: '#FBBF24',
      isDragon: false,
      isQueen: false,
      hasStarPin: true,
      hasSunflower: false,
      hasCrownTiara: false,
    };
  }

  if (k === 'hydrogen') {
    return {
      outline: '#164E63',
      hair: '#67E8F9',
      hairDark: '#06B6D4',
      hairTip: '#A5F3FC',
      earInner: '#CCFBF1',
      skin: '#FFF2ED',
      blush: '#FDA4AF',
      eyeLeft: '#C084FC',
      eyeRight: '#F59E0B',
      collar: '#0E7490',
      accent: '#FDE047',
      isDragon: false,
      isQueen: false,
      hasStarPin: true,
      hasSunflower: false,
      hasCrownTiara: false,
    };
  }

  if (k === 'carbon') {
    return {
      outline: '#18102B',
      hair: '#312352',
      hairDark: '#1F1638',
      hairTip: '#FBBF24',
      earInner: '#D97706',
      skin: '#FFF0EA',
      blush: '#FDA4AF',
      eyeLeft: '#A855F7',
      eyeRight: '#F59E0B',
      collar: '#110C22',
      accent: '#FBBF24',
      isDragon: false,
      isQueen: false,
      hasStarPin: false,
      hasSunflower: false,
      hasCrownTiara: true,
    };
  }

  if (k === 'claude') {
    return {
      outline: '#4A2511',
      hair: '#FB923C',
      hairDark: '#EA580C',
      hairTip: '#FDBA74',
      earInner: '#FEF3C7',
      skin: '#FFF2EB',
      blush: '#FCA5A5',
      eyeLeft: '#B45309',
      eyeRight: '#B45309',
      collar: '#78350F',
      accent: '#FACC15',
      isDragon: false,
      isQueen: false,
      hasStarPin: false,
      hasSunflower: true,
      hasCrownTiara: false,
    };
  }

  if (k === 'gpt') {
    return {
      outline: '#164E63',
      hair: '#E2E8F0',
      hairDark: '#94A3B8',
      hairTip: '#6EE7B7',
      earInner: '#10B981',
      skin: '#FFF1EC',
      blush: '#FDA4AF',
      eyeLeft: '#10B981',
      eyeRight: '#10B981',
      collar: '#0F172A',
      accent: '#34D399',
      isDragon: true,
      isQueen: false,
      hasStarPin: false,
      hasSunflower: false,
      hasCrownTiara: false,
    };
  }

  // queen 或 neon（紫罗兰猫娘）
  return {
    outline: '#2D2148',
    hair: '#8B7CF6',
    hairDark: '#5B4BC4',
    hairTip: '#E879F9',
    earInner: '#F9A8D4',
    skin: '#FFF0EA',
    blush: '#FDA4AF',
    eyeLeft: '#C084FC',
    eyeRight: '#F59E0B',
    collar: '#1E1B4B',
    accent: '#FBBF24',
    isDragon: false,
    isQueen: k === 'queen',
    hasStarPin: true,
    hasSunflower: false,
    hasCrownTiara: false,
  };
}

/**
 * 归一化动作名称到 6 个标准像素姿态。
 * @param {string} action
 * @param {string} state
 */
function normalizePixelAction(action, state) {
  const a = String(action || '').toLowerCase();
  if (a === 'thinking' || a === 'reading' || a === 'editing' || a === 'running' || a === 'asking' || a === 'idle') {
    return a;
  }
  const s = String(state || '').toLowerCase();
  if (s === 'parked' || s === 'sleep' || s === 'done' || s === 'landed' || s === 'waiting' || s === 'retired') {
    return 'idle';
  }
  if (s === 'needs_you') return 'asking';
  return 'thinking';
}

/**
 * 在 32×32 Canvas 上绘制像素风 AI 娘精灵与对应工具动作道具。
 * @param {HTMLCanvasElement} canvas
 * @param {{ kind: string, memberName: string, roleMode: string, state?: string, action?: string, frame?: number }} opts
 */
function drawPixelSprite(canvas, opts) {
  const W = 32;
  const H = 32;
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, W, H);

  const pal = resolvePixelPalette(opts.kind, opts.memberName, opts.roleMode);
  const frame = opts.frame ? 1 : 0;
  const action = normalizePixelAction(opts.action, opts.state);
  const asleep = action === 'idle';
  const yOff = frame === 1 && !asleep ? -1 : 0;

  const px = (x, y, col) => {
    const yy = y + yOff;
    if (x < 0 || x >= W || yy < 0 || yy >= H) return;
    ctx.fillStyle = col;
    ctx.fillRect(x, yy, 1, 1);
  };
  const rect = (x0, y0, w, h, col) => {
    for (let y = y0; y < y0 + h; y += 1) {
      for (let x = x0; x < x0 + w; x += 1) px(x, y, col);
    }
  };

  // 后发垂坠与轮廓
  rect(6, 12, 20, 14, pal.outline);
  rect(7, 13, 18, 12, pal.hairDark);
  rect(7, 22, 4, 5, pal.hairTip);
  rect(21, 22, 4, 5, pal.hairTip);

  // 猫耳 或 翡翠龙角
  if (pal.isDragon) {
    for (let dy = 0; dy < 5; dy += 1) {
      px(8 - Math.floor(dy / 2), 8 - dy, pal.outline);
      px(9 - Math.floor(dy / 2), 8 - dy, dy < 3 ? '#10B981' : '#6EE7B7');
      px(23 + Math.floor(dy / 2), 8 - dy, pal.outline);
      px(22 + Math.floor(dy / 2), 8 - dy, dy < 3 ? '#10B981' : '#6EE7B7');
    }
  } else if (!pal.hasSunflower) {
    const earDrop = asleep ? 1 : 0;
    const earBob = frame === 1 && !asleep ? -1 : 0;
    rect(6, 5 + earDrop + earBob, 5, 5, pal.outline);
    rect(7, 6 + earDrop + earBob, 3, 4, pal.hair);
    rect(8, 7 + earDrop + earBob, 2, 2, pal.earInner);

    rect(21, 5 + earDrop, 5, 5, pal.outline);
    rect(22, 6 + earDrop, 3, 4, pal.hair);
    rect(22, 7 + earDrop, 2, 2, pal.earInner);
  }

  // 头部与头发
  rect(8, 8, 16, 14, pal.outline);
  rect(9, 9, 14, 12, pal.hair);
  px(15, 7, pal.hair);
  px(16, 6, pal.hair);
  px(17, 6, pal.hairDark);

  // 领队皇冠 或 Carbon 黑金星冠
  if (pal.isQueen) {
    rect(12, 5, 8, 3, '#D97706');
    rect(13, 4, 2, 3, '#FDE047');
    rect(15, 3, 2, 4, '#FEF08A');
    rect(17, 4, 2, 3, '#FDE047');
    px(15, 6, '#A855F7');
    px(16, 6, '#F472B6');
  } else if (pal.hasCrownTiara) {
    rect(13, 6, 6, 2, '#110C22');
    px(15, 5, '#FBBF24');
    px(16, 5, '#FDE047');
    px(14, 7, '#F59E0B');
    px(17, 7, '#F59E0B');
  }

  // 脸颊与刘海
  rect(10, 14, 12, 8, pal.skin);
  rect(9, 10, 14, 4, pal.hair);
  px(11, 14, pal.hair);
  px(15, 14, pal.hair);
  px(16, 14, pal.hair);
  px(20, 14, pal.hair);

  // 发饰
  if (pal.hasStarPin) {
    px(22, 11, '#FBBF24');
    px(21, 12, '#A78BFA');
    px(22, 12, '#60A5FA');
    px(23, 12, '#F472B6');
    px(22, 13, '#FBBF24');
  } else if (pal.hasSunflower) {
    rect(20, 7, 4, 4, '#FACC15');
    rect(21, 8, 2, 2, '#78350F');
  }

  // 眼睛与动作神态
  if (asleep) {
    rect(11, 17, 3, 1, pal.outline);
    rect(18, 17, 3, 1, pal.outline);
  } else {
    rect(11, 16, 3, 3, pal.outline);
    rect(11, 17, 2, 2, pal.eyeLeft);
    px(11, 16, '#FFFFFF');
    rect(18, 16, 3, 3, pal.outline);
    rect(18, 17, 2, 2, pal.eyeRight);
    px(18, 16, '#FFFFFF');
  }

  // 阅读状态加金边小圆眼镜
  if (action === 'reading') {
    rect(10, 15, 5, 5, 'rgba(0,0,0,0)');
    rect(10, 15, 5, 1, '#D97706');
    rect(10, 19, 5, 1, '#D97706');
    px(15, 17, '#D97706');
    px(16, 17, '#D97706');
    rect(17, 15, 5, 1, '#D97706');
    rect(17, 19, 5, 1, '#D97706');
  }

  // 腮红与小嘴
  rect(10, 19, 2, 1, pal.blush);
  rect(20, 19, 2, 1, pal.blush);
  if (asleep) {
    rect(15, 20, 2, 1, '#BE185D');
  } else {
    rect(15, 20, 2, 2, '#FB7185');
  }

  // 领口与服饰
  rect(11, 23, 10, 6, pal.outline);
  rect(12, 24, 8, 5, pal.collar);
  rect(15, 24, 2, 2, pal.accent);

  // 6 大动作专属像素道具与光效
  if (action === 'thinking') {
    // 托腮小手 + 右上角星光灵感点
    rect(13, 21, 2, 2, pal.skin);
    px(26, 6 - frame, '#FDE047');
    px(27, 5 - frame, '#FEF08A');
    px(28, 6 - frame, '#FDE047');
    px(27, 7 - frame, '#F59E0B');
  } else if (action === 'reading') {
    // 左侧放大镜 + 右侧发光蓝色全息卷轴
    rect(2, 18, 4, 4, '#D97706');
    rect(3, 19, 2, 2, '#BAE6FD');
    px(5, 22, '#78350F');
    rect(23, 18, 6, 8, '#38BDF8');
    rect(24, 19, 4, 6, '#E0F2FE');
    px(25, 21, '#0284C7');
    px(26, 21, '#0284C7');
  } else if (action === 'editing') {
    // 底部发光机械键盘 + 跃动小爪子
    rect(6, 26, 20, 5, '#334155');
    rect(7, 27, 18, 3, '#E2E8F0');
    px(9, 28, '#A855F7');
    px(13, 28, '#38BDF8');
    px(17, 28, '#F472B6');
    px(21, 28, '#FBBF24');
    px(10, 25 - frame, pal.skin);
    px(21, 25 - frame, pal.skin);
  } else if (action === 'running') {
    // 右侧黑绿屏终端主机
    rect(21, 20, 9, 8, '#0F172A');
    rect(22, 21, 7, 5, '#064E3B');
    px(23, 22, '#34D399');
    px(25, 23, '#34D399');
    px(26, 22 + frame, '#6EE7B7');
  } else if (action === 'asking') {
    // 右上角高亮感叹/问号提示
    rect(25, 4 - frame, 4, 7, '#F59E0B');
    rect(26, 5 - frame, 2, 3, '#FEF08A');
    px(26, 9 - frame, '#FFFFFF');
  } else {
    // 打盹双手平放
    px(9, 26, pal.skin);
    px(10, 26, pal.skin);
    px(21, 26, pal.skin);
    px(22, 26, pal.skin);
  }
}

const pixelImgCache = new Map();

/**
 * 生成（带缓存）像素精灵 PNG Data URI，用于静态头像与 GIF 导出。
 */
function getPixelSpriteDataUri(opts) {
  const key = `${opts.kind}|${opts.memberName}|${opts.roleMode}|${opts.action || ''}|${opts.state || ''}|${opts.frame || 0}`;
  if (pixelImgCache.has(key)) return pixelImgCache.get(key);
  const cv = document.createElement('canvas');
  drawPixelSprite(cv, opts);
  const uri = cv.toDataURL('image/png');
  pixelImgCache.set(key, uri);
  return uri;
}


